'use strict';

// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} default options
*
* @example
* var o = defaults();
* // returns {...}
*/
function defaults() {
	return {
		// List of anchor directions to test for each label (all directions except "middle"):
		'anchor': [ 'top-left', 'left', 'bottom-left', 'top', 'bottom', 'top-right', 'right', 'bottom-right' ],

		// Output fields written by the transform:
		'as': [ 'x', 'y', 'opacity', 'align', 'baseline' ],

		// Boolean flag specifying whether labels should not overlap the base mark:
		'avoidBaseMark': true,

		// List of named marks that the labels should not overlap:
		'avoidMarks': [],

		// Anchor position of labels for line marks:
		'lineAnchor': 'end',

		// Index of a mark in a group mark to use as the base mark:
		'markIndex': 0,

		// Labeling method to use for area marks:
		'method': 'naive',

		// List of label offsets (in pixels) for each anchor direction:
		'offset': [ 1 ],

		// Padding in pixels by which a label may extend past the chart bounding box:
		'padding': 0
	};
}


// EXPORTS //

module.exports = defaults;
